const text = $input.first().json.result.content[0].text;
const data = JSON.parse(text);
const g = (data.data ? data.data.goalItemById : data.goalItemById) || {};
const contribution = g.contribution || '';
const subs = g.subTasks || [];
const dryRun = String(($('Webhook').first().json.query.dryRun) || '') === '1';

const CHANNELS = [
  { key:'blog',            label:'Blog',                    kind:'image', provider:'blogger',    platform:'blogger'   },
  { key:'explainer_video', label:'Explainer Video',         kind:'video', provider:'uploadpost', platform:'youtube'   },
  { key:'ig_reel',         label:'Instagram Reel',          aliases:['Instagram Reel to Post'], kind:'video', provider:'uploadpost', platform:'instagram' },
  { key:'yt_reel',         label:'YouTube Reel',            kind:'video', provider:'uploadpost', platform:'youtube'   },
  { key:'fb_post',         label:'Facebook Post',           kind:'image', provider:'uploadpost', platform:'facebook'  },
  { key:'x_post',          label:'X Post + Engagement',     kind:'image', provider:'uploadpost', platform:'x', engagement:true },
  { key:'tiktok',          label:'TikTok Post',             kind:'video', provider:'uploadpost', platform:'tiktok'    },
  { key:'linkedin',        label:'LinkedIn Post',           kind:'image', provider:'uploadpost', platform:'linkedin'  },
];
const byLabel = {}; CHANNELS.forEach(c => { byLabel[c.label] = c; (c.aliases || []).forEach(a => byLabel[a] = c); });

// parse contribution sections by "## Label"
const sectionByLabel = {};
const re = /(?:^|\n)##\s+([^\n]+)\n([\s\S]*?)(?=\n##\s+|$)/g;
let m;
while ((m = re.exec(contribution))) {
  const label = m[1].trim(); const body = m[2];
  const headline = (body.match(/\*\*([^*]+)\*\*/) || [])[1] || '';
  const script = (body.match(/Script:\s*([\s\S]*?)(?=\nB-roll:|\nCaption:|\n#|\nCTA:|$)/) || [])[1] || '';
  const brollBlock = (body.match(/B-roll:\s*([\s\S]*?)(?=\nCaption:|\n#|\nCTA:|$)/) || [])[1] || '';
  const broll = brollBlock.split('\n').map(l => l.replace(/^\s*(?:\d+\.|[-*])\s*/, '').trim()).filter(Boolean);
  const caption = ((body.match(/Caption:\s*([\s\S]*?)(?=\n#|\nCTA:|$)/) || [])[1] || '').trim();
  // image-channel prose = lines that aren't markers
  const prose = body.split('\n').filter(l => {
    const t = l.trim();
    return t && !/^\*\*/.test(t) && !/^#/.test(t) && !/^Script:/.test(t) && !/^B-roll:/.test(t)
      && !/^Caption:/.test(t) && !/^CTA:/.test(t) && !/^\d+\.\s/.test(t);
  }).join('\n').trim();
  sectionByLabel[label] = { headline, script: script.trim(), broll, caption, prose };
}

let checked = [];
subs.filter(s => s.isComplete).forEach(s => {
  const label = String(s.body || '').trim();
  const ch = byLabel[label]; if (!ch) return;
  const sec = sectionByLabel[label] || {};
  checked.push({ label, key:ch.key, provider:ch.provider, platform:ch.platform, kind:ch.kind,
    engagement:!!ch.engagement, title:(sec.headline||label),
    caption:(sec.caption||sec.prose||''), script:sec.script||'', broll:sec.broll||[], prose:sec.prose||'' });
});
// ?only=<channel key> re-runs a single channel (e.g. only=blog to correct the blog post)
const only = String(($('Webhook').first().json.query.only) || '').trim();
if (only) checked = checked.filter(x => x.key === only);

// Start's LinkedIn copy carries a __YOUTUBE_URL__ placeholder; fill it with the explainer's published
// YouTube link (yt: render-cache marker) or the blog URL, else drop it
const ytUrl = ((contribution.match(/^- yt:explainer_video:(\S+)/m) || [])[1] || '');
const blogUrlPrev = ((contribution.match(/^- \[blog\] Blog: (?:posted|updated) (\S+)/m) || [])[1] || '');
const linkUrl = ytUrl || blogUrlPrev || '';
checked.forEach(c => {
  if (c.caption) c.caption = c.caption.replace(/__YOUTUBE_URL__/g, linkUrl).trim();
  if (c.prose) c.prose = c.prose.replace(/__YOUTUBE_URL__/g, linkUrl).trim();
});

// full blog markdown from the ## Blog section (everything before the Caption:/hashtag/CTA marketing tail);
// first **headline** line becomes the Blogger post title, not body content
const blogSec = (contribution.match(/(?:^|\n)##\s+Blog\n([\s\S]*?)(?=\n##\s+|$)/) || [])[1] || '';
let blogMd = blogSec.split(/\nCaption:/)[0].replace(/\n-{3,}\s*$/, '').trim();
let blogHeadline = '';
const hm = blogMd.match(/^\*\*([^*\n]+)\*\*\s*\n/);
if (hm) { blogHeadline = hm[1].trim(); blogMd = blogMd.slice(hm[0].length).trim(); }

// minimal markdown -> HTML (headings, images, links, bold/italic/code, ol/ul, hr, paragraphs)
const mdToHtml = (md) => {
  const inline = (s) => s
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img src="$2" alt="$1" style="max-width:100%;height:auto;display:block;margin:1.2em auto;"/>')
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/(^|[\s(])\*([^*\n]+)\*(?=[\s).,;:!?]|$)/g, '$1<em>$2</em>')
    .replace(/`([^`]+)`/g, '<code>$1</code>');
  const out = []; let list = null; let para = [];
  const flushPara = () => { if (para.length) { out.push('<p>' + inline(para.join(' ')) + '</p>'); para = []; } };
  const flushList = () => { if (list) { out.push('</' + list + '>'); list = null; } };
  for (const raw of md.split('\n')) {
    const l = raw.trim();
    if (!l) { flushPara(); flushList(); continue; }
    const h = l.match(/^(#{2,4})\s+(.*)$/);
    if (h) { flushPara(); flushList(); const lv = h[1].length; out.push('<h'+lv+'>' + inline(h[2]) + '</h'+lv+'>'); continue; }
    if (/^-{3,}$/.test(l)) { flushPara(); flushList(); out.push('<hr/>'); continue; }
    const oi = l.match(/^\d+\.\s+(.*)$/);
    if (oi) { flushPara(); if (list !== 'ol') { flushList(); out.push('<ol>'); list = 'ol'; } out.push('<li>' + inline(oi[1]) + '</li>'); continue; }
    const ui = l.match(/^[-*]\s+(.*)$/);
    if (ui) { flushPara(); if (list !== 'ul') { flushList(); out.push('<ul>'); list = 'ul'; } out.push('<li>' + inline(ui[1]) + '</li>'); continue; }
    if (list) flushList();
    para.push(l);
  }
  flushPara(); flushList();
  return out.join('\n');
};
const blogHtml = blogMd ? mdToHtml(blogMd) : '';
// hashtag line in the section's marketing tail (e.g. "#AIEngineering #AgenticAI ...") -> Blogger labels
const tagLine = (blogSec.match(/^\s*(#[A-Za-z0-9_]+(?:\s+#[A-Za-z0-9_]+)*)\s*$/m) || [])[1] || '';
const blogLabels = tagLine.split(/\s+/).map(t => t.replace(/^#/, '')).filter(Boolean).slice(0, 20);
// blogpost cache marker -> update the existing Blogger post instead of creating a duplicate
const blogPostId = ((contribution.match(/^- blogpost:(\S+)\s*$/m) || [])[1] || '');

const blog = checked.find(x => x.provider === 'blogger');
const anyImage = checked.some(x => x.kind === 'image');
return [{ json: {
  goalId: $('Webhook').first().json.query.goal_id,
  idea: g.body || '', dryRun, only, originalContribution: contribution,
  anyImage, blogChecked: !!blog,
  blogTitle: blog ? (blogHeadline || blog.title || (g.body||'').slice(0,80)) : '',
  blogProse: blog ? blog.prose : '',
  blogHtml, blogPostId, blogLabels, blogUrlPrev, blogHasImg: /<img/.test(blogHtml),
  totalChannels: subs.length, checkedCount: checked.length, checked
}}];

const resp = $input.first().json;
let b64='', mime='image/png', hasImage=false;
// OpenRouter image response: choices[0].message.images[].image_url.url = data URI
try {
  const msg = resp.choices && resp.choices[0] && resp.choices[0].message;
  if (msg && Array.isArray(msg.images) && msg.images.length) {
    const u = (msg.images[0].image_url && msg.images[0].image_url.url) || msg.images[0].url || '';
    const m = u.match(/^data:(image\/[a-zA-Z+]+);base64,(.+)$/);
    if (m) { mime = m[1]; b64 = m[2]; hasImage = true; }
  }
} catch (e) {}
// Legacy Gemini format fallback: candidates[0].content.parts[].inlineData
if (!hasImage) { try {
  const parts = resp.candidates[0].content.parts || [];
  for (const p of parts) { const d = p.inlineData || p.inline_data; if (d && d.data) { mime=d.mimeType||d.mime_type||'image/png'; b64=d.data; hasImage=true; break; } }
} catch (e) {} }
const o = { json: { hasImage, mime }, pairedItem: 0 };
if (hasImage) { const buf = Buffer.from(b64,'base64'); o.binary = { data: await this.helpers.prepareBinaryData(buf,'cmo-hero.png',mime) }; }
return [o];

const P = $('Parse + Select').first().json;
let heroUrl = '';
try { const id = ($('Upload to Drive').first().json || {}).id; if (id) heroUrl = 'https://lh3.googleusercontent.com/d/' + id + '=w1600'; } catch (e) {}
const ch = {};
for (const c of (P.checked || [])) ch[c.key] = { title: c.title || c.label, caption: c.caption || '' };
return [{ json: { heroUrl, ch, goalId: P.goalId, dryRun: P.dryRun } }];

// Engage on X via Upload-Post: find this campaign's X post, reply to it with the blog as the solution.
const UP = 'Apikey <<REPLACE_ME>>';
const httpReq = (o) => this.helpers.httpRequest(o);
const P = $('Publish Prep').first().json;
let blogUrl = '';
try { blogUrl = String($('Social Sync').first().json.blogUrl || ''); } catch (e) {}
try {
  // 1) the X post to engage with: this run's Post X Photo result, else the latest matching X post in history
  let postId = '';
  try { postId = String(((($('Post X Photo').first().json || {}).results || {}).x || {}).post_id || ''); } catch (e) {}
  if (!postId) {
    const h = await httpReq({ method:'GET', url:'https://api.upload-post.com/api/uploadposts/history?limit=20',
      headers:{ Authorization: UP }, json:true, timeout:30000 });
    const xs = (h.history || []).filter(p => p.platform === 'x' && p.success && p.platform_post_id);
    const want = String((P.ch.x_post && P.ch.x_post.title) || '').trim();
    const match = xs.find(p => want && String(p.post_title || '').trim() === want) || xs[0];
    if (match) postId = String(match.platform_post_id);
  }
  if (!postId) return [{ json: { error: { message: 'no X post found to reply to' } } }];
  if (!blogUrl) return [{ json: { error: { message: 'no blog url available for engagement reply' } } }];
  // bare-domain form survives Upload-Post's URL stripping on X; X still auto-links it
  const bare = blogUrl.replace(/^https?:\/\//, '');
  const text = 'Full breakdown, with the architecture and examples, on the blog:\n' + bare;
  const body = 'user=grvpanchal&platform[]=x&title=' + encodeURIComponent(text) + '&reply_to_id=' + encodeURIComponent(postId);
  const r = await httpReq({ method:'POST', url:'https://api.upload-post.com/api/upload_text',
    headers:{ Authorization: UP, 'Content-Type':'application/x-www-form-urlencoded' }, body, timeout:120000 });
  const rj = (typeof r === 'string') ? JSON.parse(r) : r;
  const xr = ((rj || {}).results || {}).x || {};
  if (rj && rj.success && xr.success) return [{ json: { ok:true, repliedTo: postId, replyId: xr.post_id || '', url: xr.url || '', text } }];
  return [{ json: { error: { message: ('reply failed: ' + JSON.stringify(rj)).slice(0, 300) } } }];
} catch (e) {
  return [{ json: { error: { message: String(e.message || e).slice(0, 300) } } }];
}

const post = $input.first().json || {};
const P = $('Parse + Select').first().json;
const postId = String(post.id || P.blogPostId || '');
const postUrl = String(post.url || '');
const wasUpdate = !!P.blogPostId;
if (!postId) return [{ json: { done:false, error:'no blogger post id in response' } }];
const httpReq = (o) => this.helpers.httpRequest(o);
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const gq = async (query, variables) => {
  const r = await httpReq({ method:'POST', url:'https://aicivz8c3l.execute-api.ap-south-1.amazonaws.com/dev/mcp/call',
    headers:{'Content-Type':'application/json','X-API-Key':'<<REPLACE_ME>>'},
    body:{ jsonrpc:'2.0', method:'tools/call', params:{ name:'graphql_query', arguments:{ query, variables } }, id:1 },
    json:true, timeout:30000 });
  return JSON.parse(r.result.content[0].text);
};
const line = '- [blog] Blog: ' + (wasUpdate ? 'updated' : 'posted') + (postUrl ? (' ' + postUrl) : (' post ' + postId));
const mutate = (c) => {
  const ri = c.indexOf('\n# Campaign Report');
  let base = ri >= 0 ? c.slice(0, ri) : c, rest = ri >= 0 ? c.slice(ri) : '';
  const marker = '- blogpost:' + postId;
  if (/^- blogpost:.*$/m.test(base)) base = base.replace(/^- blogpost:.*$/m, marker);
  else if (base.includes('## Render Cache')) base = base.replace('## Render Cache', '## Render Cache\n' + marker);
  else base = base.trimEnd() + '\n\n## Render Cache\n' + marker + '\n';
  let c2 = base + rest;
  c2 = c2.split('\n').filter(l => !/^- \[blog\] Blog:/.test(l)).join('\n');
  return c2.trimEnd() + '\n' + line + '\n';
};
try {
  for (let a = 0; a < 4; a++) {
    const d = await gq('query G($id: ID!) { goalItemById(id: $id) { contribution } }', { id: P.goalId });
    const cur = ((((d.data || d).goalItemById) || {}).contribution) || '';
    await gq('mutation S($id: ID!, $c: String) { updateGoalItemContribution(id: $id, contribution: $c) { id } }', { id: P.goalId, c: mutate(cur) });
    await sleep(1500 + Math.floor(Math.random() * 1500));
    const v = await gq('query G($id: ID!) { goalItemById(id: $id) { contribution } }', { id: P.goalId });
    const vc = ((((v.data || v).goalItemById) || {}).contribution) || '';
    if (vc.includes('- blogpost:' + postId) && vc.includes(line)) return [{ json: { done:true, postId, postUrl, wasUpdate } }];
  }
  return [{ json: { done:false, postId, postUrl, error:'marker write kept getting clobbered' } }];
} catch (e) { return [{ json: { done:false, postId, error:String(e.message||e).slice(0,200) } }]; }

const P = $('Parse + Select').first().json;
let prep = { heroUrl: '' };
try { prep = $('Publish Prep').first().json; } catch (e) {}
const httpReq = (o) => this.helpers.httpRequest(o);
const grab = (name) => { try { const it = $(name).first(); return it ? it.json : null; } catch (e) { return null; } };
const published = [], staged = [], errors = [], brollPlans = [];

// b-roll dryRun planning (rendering itself lives in CMO Video Render)
const INTRO_FRAC=0.12, OUTRO_FRAC=0.08, CLIP_SEC=5, MAX_CLIPS=60;
const planBroll = (ch, dur) => {
  let beats = (ch.broll && ch.broll.length) ? ch.broll
            : ((String(ch.script||'').match(/[^.!?]+[.!?]+/g) || [ch.script||'']).map(s=>s.trim()).filter(Boolean));
  if (!beats.length) beats = [String(ch.title||'business')];
  const winStart = +(dur*INTRO_FRAC).toFixed(1);
  const winLen = Math.max(CLIP_SEC, dur*(1-OUTRO_FRAC) - winStart);
  const nClips = Math.min(MAX_CLIPS, Math.max(1, Math.ceil(winLen/CLIP_SEC)));
  const queries=[];
  for (let i=0;i<nClips;i++){ const t=winStart+(i+0.5)*winLen/nClips; const frac=Math.max(0,Math.min(1,t/dur));
    const bi=beats.length>1?Math.min(beats.length-1, Math.round(frac*(beats.length-1))):0; queries.push(beats[bi]||''); }
  return { winStart, winLen, nClips, queries, beatCount: beats.length };
};

const imgNodeByKey = { fb_post:'Post FB Photo', x_post:'Post X Photo', linkedin:'Post LinkedIn' };
for (const ch of (P.checked || [])) {
  if (ch.provider === 'blogger') {
    if (P.dryRun) { published.push({ label: ch.label, via: 'Blogger (dryRun)' }); continue; }
    const upd = grab('Update Blogger'), post = grab('Post to Blogger');
    const r = upd || post;
    if (r && r.url) published.push({ label: ch.label, via: (upd ? 'Blogger updated' : 'Blogger posted'), url: r.url });
    else if (r && r.error) errors.push({ label: ch.label, error: String(r.error.message || r.error).slice(0,150) });
    else staged.push({ label: ch.label, reason: 'blogger node did not run' });
    continue;
  }
  if (ch.kind === 'video') {
    if (!ch.script) { staged.push({ label: ch.label, reason: 'no script in plan' }); continue; }
    if (P.dryRun) {
      const words = String(ch.script).split(/\s+/).filter(Boolean).length;
      const estDur = Math.max(20, Math.round(words/2.5));
      const plan = planBroll(ch, estDur);
      const cov = Math.round(plan.winLen/estDur*100);
      brollPlans.push({ label: ch.label, estDurationSec: estDur, brollCoveragePct: cov, avatarPct: 100-cov,
        clips: plan.queries.length, beats: plan.beatCount, queries: plan.queries });
      published.push({ label: ch.label, via: 'video (dryRun - planned ' + plan.queries.length + ' Pexels b-roll clips, ~' + cov + 'pct b-roll / ~' + (100-cov) + 'pct avatar)' });
      continue;
    }
    published.push({ label: ch.label, via: 'video render dispatching to cmo-video (async; result appended when ready)' });
    continue;
  }
  // image channels
  if (P.dryRun) { published.push({ label: ch.label, via: 'upload-post ' + ch.platform + ' (dryRun)' }); continue; }
  if (!prep.heroUrl) { staged.push({ label: ch.label, reason: 'hero image not generated' }); continue; }
  const r = grab(imgNodeByKey[ch.key]);
  if (r && !r.error) published.push({ label: ch.label, via: 'upload-post ' + ch.platform, resp: JSON.stringify(r).slice(0,160) });
  else if (r && r.error) errors.push({ label: ch.label, error: String(r.error.message || r.error).slice(0,160) });
  else staged.push({ label: ch.label, reason: 'publish node did not run' });
  if (ch.engagement) {
    const er = grab('X Engagement');
    if (er && !er.error) published.push({ label: ch.label + ' (engagement)', via: 'X reply with blog link' + (er.url ? (' ' + er.url) : '') });
    else if (er && er.error) errors.push({ label: ch.label + ' engagement', error: String(er.error.message || er.error).slice(0,120) });
  }
}

const JWT='Apikey <<REPLACE_ME>>', CS='Bearer <<REPLACE_ME>>', CS_ACCOUNT='6a32d4389433589ea9aeadb5', USER='grvpanchal';
let prevPerf = {};
try { prevPerf.social = await httpReq({ method:'GET', url:'https://api.upload-post.com/api/analytics/'+USER+'?platforms=instagram,youtube,x', headers:{'Authorization':JWT}, json:true }); } catch (e) { prevPerf.socialError = String(e.message||e).slice(0,120); }
try { prevPerf.linkedin = await httpReq({ method:'POST', url:'https://api.connectsafely.ai/linkedin/analytics/creator', headers:{'Authorization':CS,'Content-Type':'application/json'}, body:{ accountId:CS_ACCOUNT, resultType:'growth' }, json:true }); } catch (e) { prevPerf.linkedinError = String(e.message||e).slice(0,120); }

return [{ json: { published, staged, errors, prevPerf, brollPlans, idea:P.idea, goalId:P.goalId,
  originalContribution:P.originalContribution, dryRun:P.dryRun, heroUrl:prep.heroUrl,
  blogChecked:P.blogChecked, checkedCount:P.checkedCount, totalChannels:P.totalChannels } }];

