parameters.jsCode:
const P = $('Parse + Select').first().json;
const R = $('Collect Results').first().json;
let blogUrl = '';
try { blogUrl = String($('Social Sync').first().json.blogUrl || ''); } catch (e) {}

const esc = s => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const BRAND = '#d35400';
const GREEN = '#27ae60', RED = '#e74c3c', AMBER = '#f39c12';

const pub = R.published || [], errs = R.errors || [], stag = R.staged || [];
const total = pub.length + errs.length + stag.length;
const progress = total ? Math.round(pub.length / total * 100) : 0;
const barColor = progress >= 70 ? GREEN : progress >= 40 ? AMBER : RED;

const li = (items, render, emptyMsg) => items.length
  ? items.map(i => '<li style="margin:6px 0;padding-left:4px;">' + render(i) + '</li>').join('')
  : '<li style="margin:6px 0;color:#95a5a6;">' + emptyMsg + '</li>';
const liPub = li(pub, x => '<b>' + esc(x.label) + '</b>' + (x.via ? (' &middot; <span style="color:#57606f;">' + esc(x.via) + '</span>') : '')
  + (x.url ? (' &middot; <a href="' + esc(x.url) + '" style="color:' + BRAND + ';">' + esc(x.url) + '</a>') : ''), 'Nothing published');
const liErr = li(errs, x => '<b>' + esc(x.label) + '</b> &middot; <span style="color:' + RED + ';">' + esc(x.error || 'failed') + '</span>', 'No failures');
const liStag = li(stag, x => '<b>' + esc(x.label) + '</b> &middot; <span style="color:#57606f;">' + esc(x.reason || 'skipped') + '</span>', 'Nothing staged');

const tile = (n, label, c) =>
  '<div style="flex:1;background:#f8f9fa;border-left:4px solid ' + c + ';border-radius:6px;padding:10px;">'
  + '<div style="font-size:22px;font-weight:800;color:' + c + ';">' + n + '</div>'
  + '<div style="font-size:11px;color:#57606f;">' + label + '</div></div>';
const tiles = '<div style="display:flex;gap:10px;margin:14px 0;">'
  + tile(pub.length, 'Passed', GREEN) + tile(errs.length, 'Failed', RED) + tile(stag.length, 'Staged', AMBER) + '</div>';

const blogCard = blogUrl
  ? ('<div style="background:#f8f9fa;border-left:4px solid ' + BRAND + ';border-radius:8px;padding:12px 14px;margin:14px 0;">'
   + '<div style="font-size:13px;font-weight:600;color:#2c3e50;">\u{1F517} Blog post shared across channels</div>'
   + '<div style="font-size:13px;margin-top:2px;"><a href="' + esc(blogUrl) + '" style="color:' + BRAND + ';">' + esc(blogUrl) + '</a></div></div>')
  : '';

function pad(n){ return String(n).padStart(2,'0'); }
const now = new Date();
const dateStr = pad(now.getDate()) + '-' + pad(now.getMonth()+1) + '-' + now.getFullYear();
const badge = P.dryRun ? ' <span style="font-size:11px;font-weight:600;background:rgba(255,255,255,.25);border-radius:4px;padding:2px 8px;vertical-align:middle;">DRY RUN</span>' : '';

const frag = '<div style="max-width:640px;margin:0 auto;font-family:-apple-system,Segoe UI,Roboto,sans-serif;color:#2c3e50;">'
 + '<div style="background:' + BRAND + ';color:#fff;border-radius:12px 12px 0 0;padding:18px 20px;">'
 + '<div style="font-size:13px;opacity:.85;">CMO Campaign &middot; Publish Report &middot; ' + dateStr + '</div>'
 + '<div style="font-size:20px;font-weight:700;margin-top:4px;">\u{1F4E3} ' + esc(R.idea || 'Campaign') + badge + '</div>'
 + '</div>'
 + '<div style="background:#fff;border-radius:0 0 12px 12px;padding:20px;box-shadow:0 2px 8px rgba(0,0,0,.08);">'
 + '<div style="display:flex;align-items:center;gap:14px;margin-bottom:6px;">'
 + '<div style="font-size:34px;font-weight:800;color:' + barColor + ';">' + progress + '%</div>'
 + '<div style="flex:1;background:#ecf0f1;border-radius:8px;height:14px;overflow:hidden;">'
 + '<div style="width:' + progress + '%;height:100%;background:' + barColor + ';"></div>'
 + '</div></div>'
 + '<div style="font-size:14px;color:#57606f;margin-bottom:4px;">' + pub.length + ' of ' + total + ' channels published' + (P.dryRun ? ' (dry run)' : '') + '</div>'
 + tiles + blogCard
 + '<h3 style="margin:16px 0 6px;font-size:15px;color:' + GREEN + ';">Published</h3>'
 + '<ul style="margin:0;padding-left:20px;font-size:14px;">' + liPub + '</ul>'
 + '<h3 style="margin:16px 0 6px;font-size:15px;color:' + RED + ';">Failed</h3>'
 + '<ul style="margin:0;padding-left:20px;font-size:14px;">' + liErr + '</ul>'
 + '<h3 style="margin:16px 0 6px;font-size:15px;color:' + AMBER + ';">Staged</h3>'
 + '<ul style="margin:0;padding-left:20px;font-size:14px;">' + liStag + '</ul>'
 + '<div style="margin-top:18px;font-size:11px;color:#95a5a6;text-align:right;">Generated by CMO End &middot; ' + dateStr + '</div>'
 + '</div></div>';

const pageHtml = '<!DOCTYPE html><html><head><meta charset="utf-8">'
 + '<meta name="viewport" content="width=device-width,initial-scale=1">'
 + '<title>CMO Campaign - Publish Report</title></head>'
 + '<body style="margin:0;padding:16px;background:#f4f6f8;font-family:-apple-system,Segoe UI,Roboto,sans-serif;color:#2c3e50;">'
 + frag + '</body></html>';

return [{ json: { goalId: R.goalId, rewardHtml: frag, pageHtml } }];

