try { const m = $('Save Blog Marker').first().json; if (m && m.postUrl) blogUrl = String(m.postUrl); } catch (e) {}
if (!blogUrl) { try { blogUrl = String($('Parse + Select').first().json.blogUrlPrev || ''); } catch (e) {} }
